def subject_color(subject_id: int) -> str:
    """Consistent color for a subject across all views."""
    return SUBJECT_COLORS[subject_id % len(SUBJECT_COLORS)]


def _active_config(school):
    return (
        TimetableConfig.objects.filter(school=school, is_active=True)
        .order_by("-academic_year_start")
        .first()
    )


def _get_school_or_redirect(request):
    school = get_school_for_user(request.user)
    if not school:
        messages.error(request, "No school linked to your account.")
        return None
    return school


def _published_timetable(config):
    return (
        Timetable.objects.filter(config=config, status="published")
        .order_by("-published_at")
        .first()
    )


