def _build_grid(config, timetable, classes=None):
    """Build the grid context: columns (day+slot) and per-class rows with
    merged double periods and assembly/break markers."""
    days = config.days
    slots = list(config.period_slots.all().order_by("slot_number"))

    if classes is None:
        classes = list(
            SchoolClass.objects.filter(school=config.school).order_by("sort_order")
        )

    entry_map = {}
    if timetable:
        for e in TimetableEntry.objects.filter(timetable=timetable).select_related(
            "period_slot", "school_class", "subject", "teacher", "room"
        ):
            entry_map[(e.day, e.period_slot_id, e.school_class_id)] = e

    columns = []
    for day in days:
        day_cols = []
        for slot in slots:
            day_cols.append({"slot": slot, "kind": slot.slot_type, "day": day})
        columns.append({"day": day, "slots": day_cols})

    rows = []
    for sc in classes:
        row_cells = []
        for day in days:
            for slot in slots:
                if slot.slot_type != "teaching":
                    row_cells.append({"type": "break", "label": slot.label})
                    continue
                entry = entry_map.get((day, slot.pk, sc.pk))
                if entry and entry.is_double_end:
                    continue
                if entry:
                    colspan = 2 if entry.is_double_start else 1
                    row_cells.append(
                        {
                            "type": "lesson",
                            "colspan": colspan,
                            "entry": entry,
                            "color": subject_color(entry.subject_id),
                            "locked": entry.is_locked,
                        }
                    )
                else:
                    row_cells.append({"type": "empty"})
        rows.append({"school_class": sc, "cells": row_cells})

    subject_colors_map = {
        s.pk: subject_color(s.pk) for s in Subject.objects.filter(school=config.school)
    }
    return {
        "days": days,
        "slots": slots,
        "columns": columns,
        "rows": rows,
        "subject_colors": subject_colors_map,
    }


