@login_required
def timetable_hub(request):
    school = get_school_for_user(request.user)
    if not school:
        messages.error(request, "No school linked to your account.")
        return redirect("dashboard")

    config = _active_config(school)
    published = _published_timetable(config) if config else None

    if not is_admin_or_superuser(request.user):
        if published:
            return redirect("timetable_master", timetable_id=published.pk)
        messages.info(request, "No timetable has been published yet.")
        return redirect("dashboard")

    timetables = (
        Timetable.objects.filter(config=config) if config else Timetable.objects.none()
    )
    return render(
        request,
        "timetable/hub.html",
        {
            "school": school,
            "config": config,
            "published": published,
            "timetables": timetables,
        },
    )


