@login_required
@role_required("admin")
def timetable_config_wizard(request, config_id=None):
    school = _get_school_or_redirect(request)
    if not school:
        return redirect("dashboard")

    config = None
    if config_id:
        config = get_object_or_404(TimetableConfig, pk=config_id, school=school)

    if request.method == "POST":
        action = request.POST.get("action", "save_all")

        if not config:
            year_start = int(request.POST.get("academic_year_start", 2026))
            config, _ = TimetableConfig.objects.get_or_create(
                school=school,
                academic_year_start=year_start,
                academic_year_end=year_start + 1,
                defaults={"is_active": True},
            )

        if action == "save_basic":
            config.days = request.POST.getlist("days")
            config.assembly_day = request.POST.get("assembly_day", "Monday")
            config.assembly_duration_periods = int(
                request.POST.get("assembly_duration_periods", 1)
            )
            config.is_active = True
            config.save()
            messages.success(request, "Basic setup saved.")
            return redirect("timetable_config_edit", config_id=config.pk)

        if action == "save_slots":
            config.period_slots.all().delete()
            count = int(request.POST.get("slot_count", 0))
            slot_data = []
            for i in range(1, count + 1):
                slot_type = request.POST.get(f"slot_type_{i}", "").strip()
                label = request.POST.get(f"slot_label_{i}", "").strip()
                start = request.POST.get(f"slot_start_{i}", "").strip()
                end = request.POST.get(f"slot_end_{i}", "").strip()
                if slot_type and label and start and end:
                    slot_data.append((i, slot_type, label, start, end))

            for number, slot_type, label, start, end in slot_data:
                PeriodSlot.objects.create(
                    config=config,
                    slot_number=number,
                    slot_type=slot_type,
                    label=label,
                    start_time=start,
                    end_time=end,
                )
            # Auto-calculate can_start_double
            teaching = sorted(
                PeriodSlot.objects.filter(config=config, slot_type="teaching"),
                key=lambda s: s.slot_number,
            )
            numbers = [s.slot_number for s in teaching]
            for i, ps in enumerate(teaching):
                ps.can_start_double = (
                    i + 1 < len(teaching) and numbers[i + 1] == numbers[i] + 1
                )
                ps.save(update_fields=["can_start_double"])
            messages.success(request, f"Saved {len(slot_data)} period slots.")
            return redirect("timetable_config_edit", config_id=config.pk)

        if action == "save_requirements":
            SubjectPeriodRequirement.objects.filter(config=config).delete()
            count = 0
            for key, value in request.POST.items():
                if key.startswith("req_") and key.endswith("_periods") and value:
                    parts = key.split("_")
                    class_id = int(parts[1])
                    subject_id = int(parts[2])
                    periods = int(value)
                    doubles = int(
                        request.POST.get(f"req_{class_id}_{subject_id}_doubles", 0) or 0
                    )
                    if periods > 0:
                        SubjectPeriodRequirement.objects.create(
                            config=config,
                            school_class_id=class_id,
                            subject_id=subject_id,
                            periods_per_week=periods,
                            doubles_per_week=doubles,
                        )
                        count += 1
            messages.success(request, f"Saved {count} subject requirements.")
            return redirect("timetable_config_edit", config_id=config.pk)

        if action == "toggle_availability":
            teacher_id = int(request.POST.get("teacher_id", 0))
            day = request.POST.get("day", "")
            slot_id = int(request.POST.get("slot_id", 0))
            existing = TeacherAvailability.objects.filter(
                config=config, teacher_id=teacher_id, day=day, period_slot_id=slot_id
            ).first()
            if existing:
                existing.delete()
            else:
                TeacherAvailability.objects.create(
                    config=config,
                    teacher_id=teacher_id,
                    day=day,
                    period_slot_id=slot_id,
                )
            return render(
                request,
                "timetable/_availability_cell.html",
                {
                    "teacher_id": teacher_id,
                    "day": day,
                    "slot_id": slot_id,
                    "unavailable": existing is None,
                },
            )

        if action == "add_preference":
            teacher_id = int(request.POST.get("teacher_id", 0))
            pref_type = request.POST.get("preference_type", "")
            value_raw = request.POST.get("value", "{}")
            weight = int(request.POST.get("weight", 5))
            try:
                value = json.loads(value_raw)
            except json.JSONDecodeError:
                value = {}
            if teacher_id and pref_type:
                TeacherPreference.objects.create(
                    config=config,
                    teacher_id=teacher_id,
                    preference_type=pref_type,
                    value=value,
                    weight=weight,
                )
            return redirect("timetable_config_edit", config_id=config.pk)

        if action == "delete_preference":
            pref_id = int(request.POST.get("preference_id", 0))
            TeacherPreference.objects.filter(pk=pref_id, config=config).delete()
            return redirect("timetable_config_edit", config_id=config.pk)

        if action == "add_constraint":
            subject_id = int(request.POST.get("subject_id", 0))
            constraint_type = request.POST.get("constraint_type", "")
            weight = int(request.POST.get("weight", 5))
            if subject_id and constraint_type:
                SubjectConstraint.objects.create(
                    config=config,
                    subject_id=subject_id,
                    constraint_type=constraint_type,
                    weight=weight,
                )
            return redirect("timetable_config_edit", config_id=config.pk)

        if action == "delete_constraint":
            constraint_id = int(request.POST.get("constraint_id", 0))
            SubjectConstraint.objects.filter(pk=constraint_id, config=config).delete()
            return redirect("timetable_config_edit", config_id=config.pk)

    days_checked = config.days if config else DAYS_ALL[:5]
    slots = list(config.period_slots.all().order_by("slot_number")) if config else []
    requirements = (
        list(
            SubjectPeriodRequirement.objects.filter(config=config).select_related(
                "school_class", "subject"
            )
        )
        if config
        else []
    )
    preferences = (
        list(TeacherPreference.objects.filter(config=config).select_related("teacher"))
        if config
        else []
    )
    constraints = (
        list(SubjectConstraint.objects.filter(config=config).select_related("subject"))
        if config
        else []
    )
    teachers = list(
        Teacher.objects.filter(school=school, is_active=True).order_by("first_name")
    )
    subjects = list(Subject.objects.filter(school=school).order_by("sort_order"))
    all_classes = list(SchoolClass.objects.filter(school=school).order_by("sort_order"))

    # Coefficient map for the auto-fill heuristic
    from core.models import ClassSubject

    coef_map = {
        f"{cs.school_class_id}_{cs.subject_id}": cs.coefficient
        for cs in ClassSubject.objects.filter(school_class__school=school)
    }

    unavailable_keys = (
        {
            f"{ua.teacher_id}_{ua.day}_{ua.period_slot_id}"
            for ua in TeacherAvailability.objects.filter(config=config)
        }
        if config
        else set()
    )

    return render(
        request,
        "timetable/config_wizard.html",
        {
            "school": school,
            "config": config,
            "days_all": DAYS_ALL,
            "days_checked": days_checked,
            "slots": slots,
            "requirements": requirements,
            "preferences": preferences,
            "constraints": constraints,
            "teachers": teachers,
            "subjects": subjects,
            "all_classes": all_classes,
            "coef_map": coef_map,
            "unavailable_keys": unavailable_keys,
        },
    )


