@login_required
@role_required("admin")
def rooms_manage(request):
    school = _get_school_or_redirect(request)
    if not school:
        return redirect("dashboard")

    if request.method == "POST":
        action = request.POST.get("action")
        if action == "create":
            Room.objects.create(
                school=school,
                name=request.POST.get("name", "").strip(),
                room_type=request.POST.get("room_type", "classroom"),
                capacity=int(request.POST.get("capacity", 60)),
            )
            messages.success(request, "Room created.")
        elif action == "delete":
            Room.objects.filter(pk=request.POST.get("room_id"), school=school).delete()
            messages.success(request, "Room deleted.")
        return redirect("timetable_rooms")

    rooms = Room.objects.filter(school=school)
    return render(request, "timetable/rooms.html", {"rooms": rooms, "school": school})


