def _run_solver_thread(config_id: int, problem, time_limit: float):
    """Runs in a background thread; saves the result to the database."""
    try:
        from core.solver import TimetableSolver
        from core.utils.timetable_bridge import save_result_to_db

        solver = TimetableSolver(problem)
        result = solver.solve(time_limit=time_limit)
        config = TimetableConfig.objects.get(pk=config_id)
        save_result_to_db(config, result, name=f"Auto #{config.timetables.count() + 1}")
    except Exception as exc:
        import logging

        logging.getLogger(__name__).exception("Solver thread failed")
        try:
            config = TimetableConfig.objects.get(pk=config_id)
            Timetable.objects.create(
                config=config,
                name="Failed Generation",
                status="failed",
                solver_log=str(exc),
            )
        except Exception:
            pass


@login_required
@role_required("admin")
def generate_timetable(request, config_id):
    from django.conf import settings as dj_settings

    config = get_object_or_404(TimetableConfig, pk=config_id)
    school = _get_school_or_redirect(request)
    if not school:
        return redirect("dashboard")

    from core.utils.timetable_bridge import build_problem

    problem = build_problem(config)
    if not problem.requirements:
        messages.error(
            request,
            "No subject requirements configured. Complete the wizard first.",
        )
        return redirect("timetable_config_edit", config_id=config.pk)

    time_limit = float(getattr(dj_settings, "TIMETABLE_SOLVER_TIME_LIMIT", 90))
    thread = threading.Thread(
        target=_run_solver_thread,
        args=(config.pk, problem, time_limit),
        daemon=True,
    )
    thread.start()
    messages.info(request, "Timetable generation started. This page will update.")
    return redirect("timetable_hub")


