@login_required
def timetable_teacher_view(request, timetable_id, teacher_id=None):
    timetable, school = _get_timetable_for_user(request, timetable_id)

    if teacher_id is None:
        profile = getattr(request.user, "profile", None)
        if not profile or not profile.teacher:
            messages.error(request, "No teacher record linked to your account.")
            return redirect("dashboard")
        teacher = profile.teacher
    else:
        if not is_admin_or_superuser(request.user):
            return HttpResponseForbidden("Admins only.")
        teacher = get_object_or_404(Teacher, pk=teacher_id, school=school)

    days = timetable.config.days
    slots = list(timetable.config.period_slots.all().order_by("slot_number"))
    entries = TimetableEntry.objects.filter(
        timetable=timetable, teacher=teacher
    ).select_related("period_slot", "school_class", "subject", "room")

    entry_map = {(e.day, e.period_slot_id): e for e in entries}
    grid_rows = []
    total = 0
    for slot in slots:
        row = {"slot": slot, "cells": []}
        for day in days:
            entry = entry_map.get((day, slot.pk))
            row["cells"].append({"day": day, "entry": entry})
            if entry:
                total += 1
        grid_rows.append(row)

    return render(
        request,
        "timetable/teacher_view.html",
        {
            "timetable": timetable,
            "school": school,
            "teacher": teacher,
            "days": days,
            "slots": slots,
            "grid_rows": grid_rows,
            "total_periods": total,
        },
    )


