def timetable_room_view(request, timetable_id):
    timetable = get_object_or_404(Timetable, pk=timetable_id)
    school = timetable.config.school
    days = timetable.config.days
    rooms = list(Room.objects.filter(school=school, is_active=True))
    slots = list(
        timetable.config.period_slots.filter(slot_type="teaching").order_by(
            "slot_number"
        )
    )
    entries = TimetableEntry.objects.filter(
        timetable=timetable, room__isnull=False
    ).select_related("room", "school_class", "subject")

    entry_map = {(e.room_id, e.day, e.period_slot_id): e for e in entries}
    grid = []
    for room in rooms:
        row = {"room": room, "cells": []}
        for day in days:
            for slot in slots:
                entry = entry_map.get((room.pk, day, slot.pk))
                row["cells"].append({"day": day, "slot": slot, "entry": entry})
        grid.append(row)

    return render(
        request,
        "timetable/room_view.html",
        {"timetable": timetable, "days": days, "slots": slots, "grid": grid},
    )


@login_required
@role_required("admin")
def timetable_stats(request, timetable_id):
    timetable = get_object_or_404(Timetable, pk=timetable_id)
    entries = list(
        TimetableEntry.objects.filter(timetable=timetable).select_related(
            "teacher", "subject", "school_class"
        )
    )
    workload: dict[int, dict] = {}
    for e in entries:
        w = workload.setdefault(
            e.teacher_id,
            {"name": str(e.teacher), "periods": 0, "classes": set()},
        )
        w["periods"] += 1
        w["classes"].add(e.school_class_id)

    max_load = max((w["periods"] for w in workload.values()), default=1)
    for w in workload.values():
        w["bar_pct"] = round(w["periods"] * 100 / max(max_load, 1))
        w["classes"] = len(w["classes"])

    return render(
        request,
        "timetable/stats.html",
        {
            "timetable": timetable,
            "workload": sorted(workload.values(), key=lambda w: -w["periods"]),
        },
    )


