@login_required
@role_required("admin")
def timetable_swap(request, timetable_id):
    timetable = get_object_or_404(Timetable, pk=timetable_id)
    action = request.POST.get("action", "swap")
    entry_a_id = int(request.POST.get("entry_a", 0))
    entry_b_id = int(request.POST.get("entry_b", 0))
    new_day = request.POST.get("new_day", "")
    new_slot_id = int(request.POST.get("new_slot", 0))

    with transaction.atomic():
        if action == "swap" and entry_a_id and entry_b_id:
            a = TimetableEntry.objects.get(pk=entry_a_id, timetable=timetable)
            b = TimetableEntry.objects.get(pk=entry_b_id, timetable=timetable)
            a.day, b.day = b.day, a.day
            a.period_slot_id, b.period_slot_id = b.period_slot_id, a.period_slot_id
            a.save()
            b.save()
        elif action == "move" and entry_a_id and new_day:
            a = TimetableEntry.objects.get(pk=entry_a_id, timetable=timetable)
            a.day = new_day
            a.period_slot_id = new_slot_id
            a.save()
        elif action == "clear" and entry_a_id:
            TimetableEntry.objects.filter(pk=entry_a_id, timetable=timetable).delete()

    return HttpResponse("ok")


