@login_required
@role_required("admin")
def timetable_regenerate(request, timetable_id):
    if request.method != "POST":
        return redirect("timetable_hub")
    old = get_object_or_404(Timetable, pk=timetable_id)
    config = old.config
    school = _get_school_or_redirect(request)
    if not school:
        return redirect("dashboard")

    from core.utils.timetable_bridge import build_problem

    problem = build_problem(config, locked_timetable=old)
    thread = threading.Thread(
        target=_run_solver_thread,
        args=(config.pk, problem, 90.0),
        daemon=True,
    )
    thread.start()
    messages.info(request, "Regeneration started (locked entries preserved).")
    return redirect("timetable_hub")


