def timetable_delete(request, timetable_id):
    if request.method != "POST":
        return redirect("timetable_hub")
    timetable = get_object_or_404(Timetable, pk=timetable_id)
    if timetable.status != "published":
        timetable.delete()
        messages.success(request, "Timetable deleted.")
    else:
        messages.error(request, "Unpublish the timetable before deleting it.")
