@login_required
def export_teacher_pdf(request, timetable_id, teacher_id=None):
    if teacher_id is None:
        profile = getattr(request.user, "profile", None)
        if not profile or not profile.teacher:
            messages.error(request, "No teacher record linked to your account.")
            return redirect("dashboard")
        teacher = profile.teacher
    else:
        if not is_admin_or_superuser(request.user):
            return HttpResponseForbidden("Admins only.")
        teacher = get_object_or_404(Teacher, pk=teacher_id)

    timetable = get_object_or_404(Timetable, pk=timetable_id)
    entries = TimetableEntry.objects.filter(
        timetable=timetable, teacher=teacher
    ).select_related("period_slot", "school_class", "subject")

    days = timetable.config.days
    slots = list(timetable.config.period_slots.all().order_by("slot_number"))
    entry_map = {(e.day, e.period_slot_id): e for e in entries}

    grid_rows = []
    total = 0
    for slot in slots:
        row_cells = []
        for day in days:
            entry = entry_map.get((day, slot.pk))
            row_cells.append(entry)
            if entry:
                total += 1
        grid_rows.append((slot, row_cells))

    return _render_pdf(
        request,
        "timetable/reports/teacher_card_pdf.html",
        {
            "teacher": teacher,
            "school": timetable.config.school,
            "timetable": timetable,
            "days": days,
            "slots": slots,
            "grid_rows": grid_rows,
            "total": total,
        },
        f"teacher_timetable_{teacher.teacher_code or teacher.pk}.pdf",
    )


@login_required
@role_required("admin")
def export_all_class_pdfs(request, timetable_id):
    from core.views.reports import _merge_pdf_bytes

    timetable = get_object_or_404(Timetable, pk=timetable_id)
    classes = list(
        SchoolClass.objects.filter(school=timetable.config.school).order_by(
            "sort_order"
        )
    )
    blobs = []
    for sc in classes:
        grid = _build_grid(timetable.config, timetable, classes=[sc])
        html_string = render_to_string(
            "timetable/reports/class_pdf.html",
            {
                "timetable": timetable,
                "school": timetable.config.school,
                "school_class": sc,
                "grid": grid,
            },
        )
        from weasyprint import HTML

        blobs.append(HTML(string=html_string).write_pdf())
    merged = _merge_pdf_bytes(blobs)
    response = HttpResponse(merged, content_type="application/pdf")
    response["Content-Disposition"] = (
        f'attachment; filename="all_class_timetables_{timetable.pk}.pdf"'
    )
    return response


@login_required
@role_required("admin")
def export_all_teacher_pdfs(request, timetable_id):
    from core.views.reports import _merge_pdf_bytes

    timetable = get_object_or_404(Timetable, pk=timetable_id)
    entries = TimetableEntry.objects.filter(timetable=timetable)
    teacher_ids = sorted({e.teacher_id for e in entries})
    teachers = Teacher.objects.filter(pk__in=teacher_ids).order_by("first_name")

    blobs = []
    for teacher in teachers:
        result = _render_teacher_schedule(timetable, teacher)
        blobs.append(result)

    merged = _merge_pdf_bytes(blobs)
    response = HttpResponse(merged, content_type="application/pdf")
    response["Content-Disposition"] = (
        f'attachment; filename="all_teacher_timetables_{timetable.pk}.pdf"'
    )
    return response


def _render_teacher_schedule(timetable, teacher):
    entries = TimetableEntry.objects.filter(
        timetable=timetable, teacher=teacher
    ).select_related("period_slot", "school_class", "subject")

    days = timetable.config.days
    slots = list(timetable.config.period_slots.all().order_by("slot_number"))
    entry_map = {(e.day, e.period_slot_id): e for e in entries}

    grid_rows = []
    total = 0
    for slot in slots:
        row_cells = []
        for day in days:
            entry = entry_map.get((day, slot.pk))
            row_cells.append(entry)
            if entry:
                total += 1
        grid_rows.append((slot, row_cells))

    html_string = render_to_string(
        "timetable/reports/teacher_card_pdf.html",
        {
            "teacher": teacher,
            "school": timetable.config.school,
            "timetable": timetable,
            "days": days,
            "grid_rows": grid_rows,
            "total": total,
        },
    )
    from weasyprint import HTML

    return HTML(string=html_string).write_pdf()


@login_required
@role_required("admin")
def export_master_excel(request, timetable_id):
    import openpyxl
    from openpyxl.styles import Font, PatternFill

    timetable = get_object_or_404(Timetable, pk=timetable_id)
    config = timetable.config
    days = config.days
    slots = list(config.period_slots.all().order_by("slot_number"))
    classes = list(
        SchoolClass.objects.filter(school=config.school).order_by("sort_order")
    )
    entries = TimetableEntry.objects.filter(timetable=timetable).select_related(
        "period_slot", "school_class", "subject", "teacher"
    )
    entry_map = {(e.day, e.period_slot_id, e.school_class_id): e for e in entries}

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "Master Grid"

    header_font = Font(bold=True, color="FFFFFF")
    header_fill = PatternFill(
        start_color="1F4E78", end_color="1F4E78", fill_type="solid"
    )

    ws.append(["Class"] + [f"{d[:3]} {s.label}" for d in days for s in slots])
    for cell in ws[1]:
        cell.font = header_font
        cell.fill = header_fill

    for sc in classes:
        row = [sc.name]
        for day in days:
            for slot in slots:
                entry = entry_map.get((day, slot.pk, sc.pk))
                row.append(entry.subject.code if entry else "")
        ws.append(row)

    # Sheet 2: Per-teacher summary
    ws2 = wb.create_sheet("Teacher Summary")
    ws2.append(["Teacher", "Total Periods", "Classes"])
    workload: dict[int, dict] = {}
    for e in entries:
        w = workload.setdefault(
            e.teacher_id, {"name": str(e.teacher), "n": 0, "cls": set()}
        )
        w["n"] += 1
        w["cls"].add(e.school_class.name)
    for key in sorted(workload, key=lambda k: workload[k]["name"]):
        d = workload[key]
        ws2.append([d["name"], d["n"], ", ".join(sorted(d["cls"]))])

    # Sheet 3: Room utilization
    ws3 = wb.create_sheet("Rooms")
    ws3.append(["Room", "Day", "Period", "Class", "Subject"])
    for e in entries:
        if e.room:
            ws3.append(
                [
                    e.room.name,
                    e.day,
                    e.period_slot.label,
                    e.school_class.name,
                    e.subject.code,
                ]
            )

    for sheet in wb.worksheets:
        for col in sheet.columns:
            max_len = max(len(str(c.value or "")) for c in col)
            sheet.column_dimensions[col[0].column_letter].width = min(max_len + 2, 40)

    response = HttpResponse(
        content_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    )
    response["Content-Disposition"] = (
        f'attachment; filename="timetable_{timetable.pk}.xlsx"'
    )
    wb.save(response)
    return response
